-- Contrato, Terms of Use e Self-Billing do parceiro, versão 2026-09-22, ATIVOS
-- (dono, 23/09/2026: "ativar para todos agora"). Fonte: ~/Desktop/Fixfy - documentos do parceiro/fonte.
-- Efeito: o app pede aos parceiros atuais a assinatura das 3 versões novas; o
-- onboarding (/get-started, passo Agreements) passa a mostrar estas.

-- A 229 liberava o tipo contractor_service_agreement mas nunca chegou a produção
-- (o check só aceitava terms_of_use, self_bill e workforce_*). Mesma regra dela:
ALTER TABLE public.contract_versions DROP CONSTRAINT IF EXISTS contract_versions_contract_type_check;
ALTER TABLE public.contract_versions
  ADD CONSTRAINT contract_versions_contract_type_check
  CHECK (contract_type IN (
    'terms_of_use',
    'self_bill_agreement',
    'contractor_service_agreement',
    'workforce_service_agreement',
    'workforce_employment_contract'
  ));

