VALUES ('contractor_service_agreement', '2026-09-22', 'Partner Agreement', $fx$<style>.fx-doc{--navy:#020040;--coral:#ED4B00;--ink:#1c1c2b;--grey:#5d5d6e;--light:#f4f4f8;--line:#dcdce6;font-family:Arial,Helvetica,sans-serif;color:var(--ink);font-size:10.5pt;line-height:1.55;-webkit-print-color-adjust:exact;print-color-adjust:exact;text-align:left}
