.fx-doc .cl .t{flex:1 1 auto;min-width:0}
.fx-doc .cl.l2{margin-left:40px}
.fx-doc .cl.l3{margin-left:80px}
.fx-doc .cl.sub{margin-left:40px}
.fx-doc .cl.sub .n,.fx-doc .cl.l2 .n,.fx-doc .cl.l3 .n{min-width:48px;font-weight:600;color:var(--grey)}
.fx-doc table.grid{width:100%;border-collapse:collapse;margin:10px 0 12px;font-size:9.5pt}
.fx-doc table.grid th,.fx-doc table.grid td{border:1px solid var(--line);padding:8px 10px;vertical-align:top;text-align:left}
.fx-doc table.grid th{background:var(--light);color:var(--navy);font-weight:700}
.fx-doc table.grid td:last-child{width:46%}
.fx-doc .execution{margin-top:34px;break-inside:avoid;page-break-inside:avoid}
.fx-doc .execution h2{font-size:15pt;color:var(--navy);margin:0 0 10px}
.fx-doc .sigwrap{display:grid;grid-template-columns:1fr 1fr;border:1px solid var(--line);margin-top:12px}
.fx-doc .sigcell{padding:16px}
