.fx-doc .sigcell .h{font-weight:700;color:var(--navy);font-size:10pt;margin-bottom:6px;text-transform:uppercase;letter-spacing:.04em}
.fx-doc .script{font-family:"Brush Script MT","Snell Roundhand","Segoe Script",cursive;font-size:24pt;color:var(--navy);line-height:1.1;min-height:38px;margin:6px 0 2px}
.fx-doc .sigline{border-bottom:1.5px solid var(--navy);height:38px;margin-top:8px}
.fx-doc .sigcap{font-size:8.5pt;color:var(--grey);margin-top:3px}
